import os
pids = []
try:
    for _ in range(200):
        p = os.fork()
        if p == 0:
            import time; time.sleep(5); os._exit(0)
        pids.append(p)
except OSError:
    print('FORK_LIMITED', len(pids))
else:
    print('FORKED', len(pids))

